package com.arjunren.coop;import java.math.*;import java.sql.*;
public final class AccountService{final Database db;public AccountService(Database d){db=d;}public Movement move(long accountId,String type,BigDecimal amount,String reference,long by){if(amount==null||amount.signum()<=0)throw new IllegalArgumentException("Amount must be positive");if(!type.equals("DEPOSIT")&&!type.equals("WITHDRAWAL"))throw new IllegalArgumentException("Invalid type");try(var c=db.connection()){c.setAutoCommit(false);try(var q=c.prepareStatement("SELECT balance FROM accounts WHERE id=? FOR UPDATE")){q.setLong(1,accountId);try(var r=q.executeQuery()){if(!r.next())throw new IllegalArgumentException("Account not found");var old=r.getBigDecimal(1);var next=type.equals("DEPOSIT")?old.add(amount):old.subtract(amount);if(next.signum()<0)throw new IllegalStateException("Insufficient funds");try(var u=c.prepareStatement("UPDATE accounts SET balance=?,updated_at=CURRENT_TIMESTAMP WHERE id=?");var i=c.prepareStatement("INSERT INTO ledger(account_id,type,amount,reference,performed_by) VALUES(?,?,?,?,?)",Statement.RETURN_GENERATED_KEYS)){u.setBigDecimal(1,next);u.setLong(2,accountId);u.executeUpdate();i.setLong(1,accountId);i.setString(2,type);i.setBigDecimal(3,amount);i.setString(4,reference);i.setLong(5,by);i.executeUpdate();try(var k=i.getGeneratedKeys()){k.next();c.commit();return new Movement(k.getLong(1),accountId,type,amount,next);}}}}catch(SQLException e){c.rollback();if("23505".equals(e.getSQLState()))throw new IllegalStateException("Duplicate reference");throw e;}}catch(SQLException e){throw new IllegalStateException(e);}}public record Movement(long id,long accountId,String type,BigDecimal amount,BigDecimal balance){}}
